-- Platsbeskrivningar, omgång 6 (94 platser utan egen hemsida).
-- Skrivna med egna ord utifrån Wikipedia, Länsstyrelsen, kommunerna och platsernas egna Facebook/Instagram.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Vidsträckt sandstrand i Skånes sydöstra hörn', description = 'Sandhammaren ligger i Löderups socken och är Skånes sydöstligaste hörn. Stranden är känd för sin vita, finkorniga sand och har flera gånger röstats fram som en av Sveriges finaste stränder. Här finns en vid strand med dyner och tallskog innanför, som passar både för bad och lek på sommaren och för långa promenader året runt. Vid Sandhammaren finns också två sevärdheter med anknytning till sjöfarten: fyrplatsen och den gamla räddningsstationen. Strömmarna kan vara starka, så det är bra att vara försiktig vid bad.' where id = 5; -- Sandhammaren
update public.places set short_description = 'Hantverksbageri och café i Simrishamn', description = 'Bagaren & Konditorn är ett hantverksbageri på Österlen som drivs av ett gift par. Som namnet säger möts här två yrken: bagarens bröd och konditorns bakverk. I caféet kan man ta en fika med något nybakat eller äta lunch, och en av de mest omtyckta lunchrätterna är bakad potatis med olika röror att välja mellan, till exempel räkröra. Bageriet ligger i Simrishamn, så det passar bra att stanna till under en dag i stan. Det går också bra att köpa med sig bröd hem.' where id = 7; -- Bagaren och Konditorn
update public.places set short_description = 'Sandstrand mellan Stenshuvud och Vik', description = 'Knäbäckshusens strand, även kallad Rörums strand, är en sandstrand strax öster om Rörum på Österlen. Norr om stranden ligger Stenshuvud och söder om den fiskeläget Vik. Stranden har ljus, finkornig sand och klart vatten, och den omges av skog och branta backar ner mot havet. Det har gjort platsen till ett populärt utflyktsmål, särskilt under sommaren. Vägen ner till stranden går genom naturen, så det är bra att ha bekväma skor. Parkeringen kan bli full under högsäsong.' where id = 9; -- Knäbäckshusens strand
update public.places set short_description = 'Kyrka i Tomelilla med glasmålningar', description = 'Tomelilla kyrka började som ett gravkapell, som byggdes 1908 efter ritningar av arkitekten Alfred Arwidius. På den tiden hörde Tomelilla till Tryde församling, men man ville ha ett kapell mitt i orten. När Tomelilla blev en egen församling 1926 byggdes kapellet om och blev församlingskyrka. Kyrkan har renoverats flera gånger sedan dess, senast på 1970-talet. Korfönstren och ett par fönster i långhuset har glasmålningar av konstnären Martin Sjöblom från Skepparp. Kyrkan hör i dag till Tomelillabygdens församling.' where id = 19; -- Tomelilla Kyrka
update public.places set short_description = 'Romansk kyrka från 1100-talet', description = 'Östra Ingelstads kyrka byggdes omkring år 1150 i romansk stil och tillskrivs stenmästaren Carl. Tornet och vapenhuset kom till senare. I kyrkorummet finns medeltida kalkmålningar som kanske målades av Bjäresjömästaren, och långhuset och koret har massiva tunnvalv av kalksten. Dopfunten av sandsten är från 1100-talet, medan altaruppsatsen och predikstolen är från 1600-talet. I kyrkan finns också en mindre klocka gjuten 1755 i Malmö. Kyrkan tillhör Smedstorps församling och är ett fint exempel på Österlens medeltida kyrkor.' where id = 25; -- Östra Ingelstads Kyrka
update public.places set short_description = 'Kyrka med gravmonument från 1595', description = 'Smedstorps kyrka byggdes 1867 och har ett ovanligt långt långhus, ett torn och en halvrund absid. Delar av den gamla kyrkans murar bevarades när den nya kyrkan byggdes. Vid kyrkan står ett gravmonument av marmor, kalksten och alabaster över riksrådet Anders Bing, den siste av släkten Bing som ägde Smedstorps slott. På monumentet finns en dikt som Jakob I av England skrev till honom. Monumentet utfördes 1595 av Hans van Steenwinckel den äldre. Kyrkan är församlingskyrka i Smedstorps församling.' where id = 27; -- Smedstorps Kyrka
update public.places set short_description = 'Nationalpark med utsikt, bokskog och stränder', description = 'Stenshuvuds nationalpark bildades 1986 och är 400 hektar stor. På en liten yta ryms lummig lövskog, blomrika ängar, hedar, sandstränder och en klippstrand. Från bergets norra topp, 96 meter över havet, ser man långt ut över Östersjön. Vid huvudentrén ligger naturum, och fem markerade slingor går genom parken, bland annat till toppen och ner till havet. I juni blommar orkidéängen. Här finns också en 4000 år gammal hällkista och rester av en fornborg. Det finns grillplatser, en tältplats och tre entréer med parkering.' where id = 29; -- Stenshuvuds nationalpark
update public.places set short_description = 'Strand och naturreservat vid Hanöbukten', description = 'Haväng ligger vid Hanöbuktens södra del, norr om Stenshuvud och nära Brösarps backar, och är ett populärt utflyktsmål på Österlen. Området ingår i naturreservatet Haväng och Vitemölla strandbackar, med ett hedliknande landskap, ovanlig sandstäppsvegetation och en rik flora och fauna. Vid Haväng finns Havängsdösen, en grav från stenåldern. Där Verkeån mynnar ut i havet finns på havsbotten rester av en tallskog från äldre stenåldern. Härifrån kan man vandra längs kusten mot Vitemölla och Kivik.' where id = 30; -- Haväng
update public.places set short_description = 'Skeppssättning med 59 stenar vid havet', description = 'Ales stenar är en fornlämning av typen skeppssättning, belägen på Kåsebergaåsen vid byn Kåseberga på Skånes sydkust. Skeppssättningen består av 59 stenar och dateras vanligen till vendeltiden, omkring år 540 till 790. Platsen hette förr Heds stenar, och namnet Ales stenar fick den på 1800-talet. Namnet tolkas troligen som stenarna på den väldiga åsen. Från åsen har man utsikt över havet och kusten. Det är en kort promenad upp från Kåseberga, och platsen är öppen att besöka året runt.' where id = 36; -- Ales stenar
update public.places set short_description = 'Medeltida kyrka vid Brösarps backar', description = 'Ravlunda kyrka ligger strax söder om Brösarps backar, någon kilometer från Östersjön, och tillhör Kiviks församling. Kyrkan byggdes omkring år 1200, och under 1400-talet tillkom tornet och senare en korsarm i norr. Inne i kyrkan finns kalkmålningar från 1200-talet, bland annat en Kristoffersbild, och målningar från 1400-talet av Vittskövlemästaren. På väggen bredvid predikstolen finns en målad inskription om svenskarnas härjningar i trakten 1612. På kyrkogården ligger författaren Fritiof Nilsson Piraten begravd.' where id = 38; -- Ravlunda Kyrka
update public.places set short_description = 'Kyrka från 1868 med berömd dopfunt', description = 'Tryde kyrka byggdes 1868 efter ritningar av Edvard von Rothstein och tog bara sex månader att uppföra. Den bekostades av Johan Petter Hintze, som ägde Kåseholm och själv övervakade bygget. Kyrkan ersatte en medeltida kyrka från omkring 1160. Mest känd är kyrkan för sin dopfunt i sandsten, huggen omkring 1160 av stenmästaren Majestatis, som därför också kallas Trydemästaren. Dopfunten vann en bronsmedalj på världsutställningen i Paris 1867. Predikstolen är från 1618. Kyrkan tillhör Tomelillabygdens församling.' where id = 44; -- Tryde Kyrka
update public.places set short_description = 'Gråstenskyrka från 1869 med medeltida klocka', description = 'Spjutstorps kyrka invigdes första advent 1869 och är byggd av gråsten och tegel, med torn och halvrund sakristia. Där kyrkan ligger fanns tidigare en medeltida stenkyrka, som revs när den nya var färdig. Altartavlan, som visar Kristi uppståndelse, är målad av Pehr Hörberg. Dopfunten är från 1200-talet, och vid ingången står en offerstock från 1438. Den större av kyrkans två klockor är också från 1438. Kyrkogården omges av murverk och kallmur. Kyrkan tillhör Brösarp-Tranås församling.' where id = 45; -- Spjutstorps Kyrka
update public.places set short_description = 'Nygotisk tegelkyrka från 1900', description = 'Glemminge kyrka i Glemmingebro är byggd av tegel i nygotisk stil, med torn och tresidigt kor. Den ritades av Peter Boisen och invigdes den 31 juli 1900. Kyrkan ersatte en medeltida kyrka från 1100-talet i romansk stil. I kyrkan finns en dopfunt i sten från 1100-talet, bevarad från den gamla kyrkan, och en nyare dopfunt i trä från 1739. Kyrkan tillhör i dag Löderups församling och var tidigare församlingskyrka i Glemminge församling. Den ligger mitt i byn, nära Glimmingehus.' where id = 46; -- Glemminge Kyrka
update public.places set short_description = 'Naturreservat med ek och bok på åsen', description = 'Listarumsåsen är ett naturreservat i Tomelilla kommun, inte långt från Smedstorp. Området har varit skyddat sedan 1976 och är 59 hektar stort. Reservatet ligger på en rullstensås, en lång rygg av sand och sten som lämnades kvar när inlandsisen smälte. Förr var marken öppen betesmark med buskar och enstaka träd, men i dag växer här en skog av ek och bok. Det gör åsen till ett fint ställe för en lugn promenad i lövskog, särskilt på våren och hösten.' where id = 49; -- Listarumsåsen
update public.places set short_description = 'Medeltida kyrka med kalkmålningar av syndafallet', description = 'Östra Hoby kyrka har en absid från första halvan av 1100-talet, kyrkans äldsta del. Under senare delen av 1100-talet byggdes långhuset och det breda, kraftiga tornet, och det var ovanligt att kyrkor fick torn så tidigt. På 1400-talet slogs valv och målades kalkmålningar av Fjälkingemästaren. I långskeppets västra del finns ovanliga takmålningar av Evas skapelse och syndafallet. Dopfunten är gjord av Trydemästaren, och predikstolen och altaret är från 1600-talet. Kyrkan är församlingskyrka i Gärsnäs församling.' where id = 54; -- Östra Hoby Kyrka
update public.places set short_description = 'Skånes enda kvarvarande rundkyrka', description = 'Valleberga kyrka är känd för att vara Skånes enda kvarvarande rundkyrka. Den byggdes av kalksten i mitten av 1100-talet, och det är oklart om den runda formen är den ursprungliga. Till rundkyrkan hör en kastal och en stor tillbyggnad, som gör att den runda delen nästan ser ut som ett bihang. Kyrkan har en kyrkogård som omges av ett järnstaket. Den tillhör Löderups församling och ligger i Valleberga, inte långt från Kåseberga och Ales stenar. En ovanlig kyrka som är värd ett stopp.' where id = 57; -- Valleberga Kyrka
update public.places set short_description = 'Kyrka från 1870-talet med medeltida dopfunt', description = 'Ingelstorps kyrka ritades av Albert Törnqvist och byggdes 1872–1874. Tidigare hade församlingen en romansk stenkyrka, och portalskulpturer från den finns i dag på Lunds universitets historiska museum. Delar av den medeltida kyrkans torn finns kvar i det nuvarande tornet. Dopfunten höggs omkring år 1200 och är utsmyckad med bladrankor och lejon. Orgeln byggdes 1883 i Köpenhamn och är mekanisk. Kyrkan tillhör Löderups församling och ligger i Ingelstorp på södra Österlen.' where id = 58; -- Ingelstorps Kyrka
update public.places set short_description = 'Stenugnsbakad pizza i Kivik', description = 'Kiviks Restaurang Pizzeria bakar sina pizzor i vedeldad stenugn, med råvaror från Italien. Vedugnen ger en snabb gräddning i hög värme, och det märks på botten och kanterna. Restaurangen ligger i Kivik, fiskeläget vid Hanöbukten som är känt för sina äpplen och sin marknad. Här passar det bra att äta efter en dag vid havet, i Stenshuvuds nationalpark eller bland Kiviks fruktodlingar. Det går också att ta med pizzan och äta den någon annanstans, till exempel vid hamnen.' where id = 60; -- Kiviks Restaurang Pizzeria
update public.places set short_description = 'Romansk kyrka med Carl Blochs altartavla', description = 'Hörups kyrka byggdes på 1100-talet i romansk stil. Under 1400-talet slogs valven, och 1848 förlängdes kyrkan österut. Kyrkans altartavla är originalet till Carl Blochs målning Christus Consolator. Predikstolen ska ha gjorts av Jacob Kremberg, och dopfunten med palmettbård skulpterades på 1100-talet. Här finns också ett krucifix i ek från början av 1500-talet. Den nuvarande orgeln byggdes 1907 i Göteborg och är mekanisk. Kyrkan tillhör Löderups församling och ligger i den lilla byn Hörup.' where id = 61; -- Hörups Kyrka
update public.places set short_description = 'Sankta Maria kyrka från 1840-talet', description = 'Sankta Maria kyrka, även kallad Borrby kyrka, byggdes 1838–1841 efter ritningar av Jacob Wilhelm Gerss. Den ersatte en stenkyrka från 1100-talet med kalkmålningar av Snårestadsgruppen, och akvarellkopior av målningarna finns i den nya kyrkans sakristia. Från början var kyrkan enkel och stilren, men under 1800-talet fick den fler utsmyckningar, bland annat en stor tornspira med fyra mindre torn. Kyrkan har målade fönster från 1910–1912. Dopfunten är bevarad från den gamla kyrkan. Kyrkan tillhör Gärsnäs församling.' where id = 63; -- Borrby Kyrka
update public.places set short_description = 'Välbevarad medeltida kyrka i Hannas', description = 'Hannas kyrka byggdes troligen under senare delen av 1100-talet och har en mycket välbevarad medeltida karaktär. Den ursprungliga romanska kyrkan hade halvrund absid, kor och långhus, och under 1400-talet tillkom valv, ett kraftigt trappgavelstorn och ett vapenhus. Bänkarna har gamla allmogemålningar och gårdsnummer. Kyrkans äldsta inventarie är den rikt skulpterade dopfunten av stenmästaren Sighraf, lika gammal som kyrkan. Vissa scener i filmen Den bästa av mödrar spelades in här. Kyrkan tillhör Gärsnäs församling.' where id = 68; -- Hannas Kyrka
update public.places set short_description = 'Kyrka med runt västtorn vid Bollerups borg', description = 'Bollerups kyrka ligger i Bollerups by intill Bollerups borg och grundlades på 1100-talet. Den är en av fyra skånska kyrkor med ett runt västtorn. Långhus, kor och absid byggdes på 1100-talet och tornet i slutet av samma århundrade, allt av huggen kalksten från bygden. Kyrkan byggdes troligen av släkten Due, som är de första kända ägarna av Bollerup. Dopfunten är från omkring år 1200, och valven slogs på 1400-talet. Kyrkan tillhör Smedstorps församling.' where id = 70; -- Bollerups Kyrka
update public.places set short_description = 'Kyrka från 1849 på medeltida grund', description = 'Hammenhögs kyrka byggdes 1849, delvis på den gamla kyrkans grund, efter ritningar av Carl Georg Brunius. Den medeltida kyrkan hade två torn, och av dem finns bara den nedre delen av ett kvar. I kyrkan finns två klockor: den stora har en inskrift i munkstil med Elisabets hälsning till Maria, och den yngre är från 1575. Runt kyrkan restes en mur 1851, som senare ersattes av ett smitt järnstaket. Kyrkan är församlingskyrka i Gärsnäs församling och ligger mitt i Hammenhög.' where id = 71; -- Hammenhögs Kyrka
update public.places set short_description = 'Kyrka med inredning från 1598', description = 'Tosterups kyrka byggdes på 1100-talet men byggdes om 1598. Här finns kyrkomålningar från 1400-talet, två målningar från 1500-talet och inredning från 1700-talet. Bänkinredningen är från ombyggnaden 1598. På 1950-talet upptäckte man att den norra väggen var den medeltida kyrkans, med en romansk port och fönster, byggd i kalksten under första halvan av 1100-talet. Kyrkan ligger nära Tosterups slott och tillhör Smedstorps församling. Den är ett intressant exempel på hur kyrkor byggts om genom århundradena.' where id = 72; -- Tosterups Kyrka
update public.places set short_description = 'Kyrka med kalkmålningar från 1300-talet', description = 'Stora Köpinge kyrka har sitt ursprung i 1100-talet och byggdes ut under 1200-talet. Tornet byggdes 1860. Inne i kyrkan finns kalkmålningar från 1300-talet som tillskrivs Snårestadsmästaren. Bland inventarierna finns en altaruppsats med baldakin från omkring 1610, en predikstol från 1597 och en romansk dopfunt. Orgeln byggdes 1894 av E A Setterquist & Son i Örebro och är mekanisk. Kyrkan tillhör Stora Köpinge församling och ligger i byn Stora Köpinge, inte långt från Ystad.' where id = 79; -- Stora Köpinge Kyrka
update public.places set short_description = 'Nyklassicistisk kyrka från 1873', description = 'Kverrestads kyrka i Kvärrestad byggdes 1871–1873 i nyklassicistisk stil. Socknen hade tidigare en medeltida kyrka i romansk stil. Kyrkan har ett torn med spira och en tresidig, smalare sakristia. Den invigdes söndagen den 2 november 1873, och över 1500 personer var med. Byggmästare var Peter Eneberg från Kivik, och arkitekt var Johan Fredrik Åbom. Kyrkan tillhör Smedstorps församling och ligger i det öppna landskapet mitt på Österlen, söder om Smedstorp.' where id = 83; -- Kverrestads Kyrka
update public.places set short_description = 'Restaurang vid Södra hamnen i Brantevik', description = 'Branterøgen är en restaurang intill Södra hamnen i Brantevik på Österlen. Brantevik är ett gammalt fiskeläge söder om Simrishamn, känt för sina låga hus, smala gator och sin historia som hemhamn för många segelfartyg. Från restaurangen har man nära till vattnet och hamnmiljön, och det passar bra att kombinera ett besök med en promenad genom byn eller längs kusten. Kolla gärna öppettiderna innan, eftersom mindre restauranger vid kusten ofta har kortare säsong.' where id = 97; -- Branterögen
update public.places set short_description = 'Ekologiskt hembageri och café i Sankt Olof', description = 'Byvägen 35 är ett ekologiskt hembageri och café i Sankt Olof. Här bakas surdegsbröd som gräddas i stenugn, och i caféet kan man fika på det som kommit ut ur ugnen samma dag. Bageriet har ett stort antal följare i sociala medier och lockar besökare från hela trakten. Sankt Olof är en liten ort mitt på Österlen, känd för sin medeltida kyrka och sitt läge mellan Kivik och Simrishamn. Det är lätt att ta en omväg hit under en tur på Österlen.' where id = 111; -- Byvägen 35
update public.places set short_description = 'Krog och kafé i Baskemölla', description = 'Tjörnedala Krog & Kafé ligger i Baskemölla, ett litet fiskeläge vid kusten norr om Simrishamn. Här serveras mat lagad på goda råvaror och bakverk med säsongens frukter och bär. Man kan alltså komma hit både för en riktig måltid och för en fika. Baskemölla är en lugn plats med gamla hus och nära till havet, och längs kusten går det att promenera mot Vik och Simrishamn. Kolla gärna öppettiderna innan, eftersom kaféer och krogar vid kusten ofta har säsongsöppet.' where id = 112; -- Tjörnedala Krog & Kafé
update public.places set short_description = 'Restaurang och logi i Smedstorp', description = 'Smedjans Mat & Logi i Smedstorp är en restaurang med fokus på närodlade råvaror, och som namnet säger finns det också logi, så man kan stanna över natten. Smedstorp ligger i Tomelilla kommun mitt på Österlen, med Smedstorps slott och Listarumsåsens naturreservat i närheten. Härifrån är det nära till både slätten, kusten och skogsbygden längre norrut. Det gör stället till en bra bas för den som vill upptäcka Österlen i lugn takt. Boka gärna bord och rum i förväg.' where id = 118; -- Smedjans Mat & Logi
update public.places set short_description = 'Pizzeria med italienska delikatesser i Simrishamn', description = 'Aldo''s Pizza & Italienska Delikatesser i Simrishamn kombinerar pizzeria med försäljning av italienska delikatesser. Man kan alltså både äta en pizza på plats och köpa med sig italienska varor hem till det egna köket. Simrishamn är Österlens största ort, med hamn, kullerstensgator och små butiker i centrum. Pizzerian passar bra för en enkel lunch eller middag under en dag i stan, och det går att ta med maten och äta den vid hamnen eller stranden.' where id = 121; -- Aldo’s Pizza & Italienska Delikatesser
update public.places set short_description = 'Restaurang i Kivik med italiensk inspiration', description = 'Tryffelsvinet är en restaurang i Kivik som hämtar sin inspiration från Italien och Centraleuropa. Restaurangen har öppet både till lunch och på kvällen, så man kan välja mellan en lunch mitt på dagen och en längre middag. Kivik ligger vid Hanöbukten och är känt för äpplen, marknaden och närheten till Stenshuvuds nationalpark. Ett besök här passar bra efter en dag i naturen eller vid havet. Kolla gärna öppettiderna innan, och boka bord om ni är flera.' where id = 125; -- Tryffelsvinet
update public.places set short_description = 'Enkelt bed and breakfast mitt i Kivik', description = 'Systrarna på Kivik är ett bed and breakfast på Kiviks Stora väg mitt i Kivik. Rummen är enkla, med mjuka och bäddade sängar, och de flesta har handfat och spegel. Toalett och dusch finns intill rummen, och ett av rummen har egen toalett. Här finns enkelrum, dubbelrum och familjerum. Gästerna har tillgång till ett allrum med tv, böcker och tidningar, där man kan koppla av, spela ett spel eller ta något kallt från baren. Från Systrarna är det nära till hamnen och Kiviks restauranger.' where id = 126; -- Systrarna på Kivik
update public.places set short_description = 'Café mitt i Simrishamn', description = 'Café Kagan är ett café mitt i Simrishamn, som beskriver sig själv som en naturlig träffpunkt i hjärtat av Österlen. Hit kommer man för en fika, en kopp kaffe eller en paus i promenaden genom stan. Caféet har öppet på vardagar och lördagar. Simrishamn är Österlens största ort, med hamn, kullerstensgator och små butiker, och det är nära till både hamnen och stranden härifrån. Kolla gärna aktuella öppettider innan, eftersom de kan ändras med säsongen.' where id = 132; -- Café Kagan Simrishamn
update public.places set short_description = 'Medeltida kyrka nära Glimmingehus', description = 'Bolshögs kyrka ligger i byn Bolshög nära Glimmingehus och byggdes i mitten av 1100-talet. År 1869 fick kyrkan ett nytt kor med korsarmar och en halvrund sakristia, och den känns igen på sitt flacka tak. Dopfunten är från slutet av 1100-talet och tillskrivs Blentarpsgruppen. Altaruppsatsens mittparti har en alabasterrelief från mitten av 1500-talet, med Kristi uppståndelse, utförd i Antwerpen. I kyrkan finns två predikstolar, och den äldre, från 1708, är rikt utsmyckad. Kyrkan tillhör Gärsnäs församling.' where id = 133; -- Bolshögs Kyrka
update public.places set short_description = 'Medeltida kyrka ombyggd under 1800-talet', description = 'Östra Nöbbelövs kyrka byggdes på 1100-talet, men av den första kyrkan finns i dag bara långhusets murar kvar. På 1400-talet fick kyrkan valv och ett trappgavelstorn. Under 1800-talet byggdes den om två gånger: 1849–1850 fick den nya valv, en sakristia och en förlängning österut, och 1896 revs trappgavelstornet och ersattes av det nuvarande tornet. Dopfunten är från 1100-talet och lika gammal som kyrkans äldsta delar, och altaruppsatsen är från 1735. Kyrkan tillhör Simrishamns församling.' where id = 136; -- Östra Nöbbelövs Kyrka
update public.places set short_description = 'Museum med tusentals fiskedrag', description = 'Fiskedragsmuseet i Simrishamn är ett museum helt ägnat åt fiskedrag. Här visas flera tusen drag, från 1800-talet fram till 2000-talet, så man kan följa hur sportfiskets redskap har förändrats under mer än hundra år. Samlingen passar både den som fiskar själv och den som är nyfiken på hantverk, design och lokal historia. Simrishamn har en lång historia som fiskeläge och hamnstad, vilket gör museet till ett passande stopp i stan. Kolla gärna öppettiderna innan ni åker, eftersom små museer ofta har begränsat öppet.' where id = 145; -- Fiskedragsmuseet
update public.places set short_description = 'Sjöfararnas kyrka mitt i Simrishamn', description = 'Sankt Nicolai kyrka ligger i centrala Simrishamn och är helgad åt Sankt Nicolaus, sjömännens skyddshelgon. Det är okänt när kyrkan först byggdes, men den äldsta delen är det nuvarande koret, som från början var ett litet fiskarkapell. Sedan dess har kyrkan byggts ut flera gånger. År 1953 togs putsen bort, och sedan dess syns murarna av kvartsit. En stor del av golvet täcks av gravstenar. Predikstolen är från 1626, från Kristian IV:s tid, och har latinska inskriptioner. Kyrkan är församlingskyrka i Simrishamns församling.' where id = 147; -- Sankt Nicolai Kyrka
update public.places set short_description = 'Barockslott med vallgravar och vinkällare', description = 'Kronovalls slott ligger mellan Tomelilla och Brösarp. Huvudbyggnaden uppfördes 1760 och byggdes om på 1890-talet till ett slott i fransk barockstil, med tornprydda flyglar, efter ritningar av Isak Gustaf Clason. Slottet ligger på en holme omgiven av vallgravar. Det har ägts av bland andra Gustaf Persson Banér, familjen Hamilton och en gren av ätten Sparre. I dag drivs Kronovall som vinslott, där svenskt mousserande vin lagras i källaren åtta meter under marken. Här finns också hotell, restaurang och vincafé. Slottet räknas som ett av Skånes kända spökslott.' where id = 150; -- Kronovalls Vinslott
update public.places set short_description = 'Romansk kyrka med runstenar i trädgården', description = 'Simris kyrka ligger i byn Simris och är från 1100-talet. Från början var den en romansk absidkyrka med ett mycket brett torn. År 1905 byggdes den om ordentligt, och långhuset blev både bredare och högre. Samtidigt murades den speciella sydportalen in på sin ursprungliga plats. I koret finns kalkmålningar från 1400-talet. Dopfunten är lika gammal som kyrkan och tillskrivs Trydemästaren. I prästgårdens trädgård, vid en av ingångarna, står två runstenar som tidigare satt inmurade i kyrkogårdsmuren. Kyrkan är församlingskyrka i Simrishamns församling.' where id = 152; -- Simris Kyrka
update public.places set short_description = 'Kyrka vars exteriör är orörd sedan 1500', description = 'Järrestads kyrka, även kallad Sankt Johannes kyrka, har ett långhus, ett kor och en rund absid från 1100-talet. På 1400-talet förlängdes kyrkan västerut och fick ett torn, och samtidigt välvdes kyrkorummet och fick större fönster. Sedan år 1500 har kyrkans exteriör inte förändrats. Predikstolen är från 1635, när Kristian IV var kung, och altartavlan med motivet Getsemane är signerad av Johan Gustaf Sandberg 1849. Kyrkogården omges av järnstaket och kallmur. Kyrkan hör till Simrishamns församling.' where id = 154; -- Järrestads Kyrka
update public.places set short_description = 'Kyrka på platsen för ett medeltida kloster', description = 'Östra Tommarps kyrka står på platsen för en liten stenkyrka från 1100-talet. Under medeltiden var den kyrka för Tommarps kloster, som tillhörde premonstratensorden. När den gamla kyrkan revs hittade man mycket bly i murarna, som hade runnit ner från taket vid en brand. Den nuvarande kyrkan byggdes 1857 i nygotisk stil, och tornet byggdes 1888. Altartavlan Christus Consolator från 1886 är en kopia av Carl Blochs tavla i Hörups kyrka. I sakristian finns en målad stjärnhimmel. Kyrkan tillhör Gärsnäs församling.' where id = 156; -- Östra Tommarps Kyrka
update public.places set short_description = 'Vallfartskyrka helgad åt Sankt Olof', description = 'Sankt Olofs kyrka är en välkänd vallfartskyrka, och den har gett hela byn dess namn. Byn hette förr Lunkende, men kyrkan var Danmarks största helgedom åt den norske helgonkungen Olof, och till slut glömdes det gamla namnet bort. I byn finns också offerkällan Sankt Olofs källa. Kyrkan byggdes under tidig medeltid, och på 1400-talet tillkom ett tvåskeppigt långhus, kanske för att ta emot fler pilgrimer. Förr fanns nio altare i kyrkan, och fem av helgonbilderna finns kvar. Kyrkan tillhör Simrishamns församling.' where id = 158; -- Sankt Olofs Kyrka
update public.places set short_description = 'Brant klintkust med betesmark och utsikt', description = 'Hammars backar är en del av naturvårdsområdet Hammars backar–Kåsebergaåsen i Ystads kommun, som bildades 1996 och är 675 hektar stort. Området består av en brant klintkust med betade backar som går ner mot havet. Från höjderna har man vid utsikt över Östersjön och kusten. Här ligger också Kåsebergaåsen, där fornlämningen Ales stenar står. Backarna passar bra för promenader och vandring, och betesdjuren håller landskapet öppet. Tänk på att visa hänsyn till djuren och att stänga grindar efter dig.' where id = 159; -- Hammars Backar
update public.places set short_description = 'Ett av Skånes minsta fiskelägen', description = 'Gislövshammar är ett av Skånes minsta fiskelägen och ligger söder om Simrishamn, inte långt från Skillinge. Bebyggelsen växte fram i början av 1800-talet. Husen byggdes till stor del av material från platsen: på uddens kalkstensklippa bröts kalkflis till väggarna, och på stranden byggdes en kalkugn där kalkstenen brändes till kalk. Folk levde främst på fiske och sjöfart. I dag är Gislövshammar en lugn plats med klippor, hav och utsikt, och den passar fint för en promenad längs kusten.' where id = 160; -- Gislövshammar
update public.places set short_description = 'Naturreservat med fälad och sandstenshällar', description = 'Bäckhalladalen är ett naturreservat strax norr om Simrishamn. Det har varit skyddat sedan 1992, är 140 hektar stort och ingår i Natura 2000. Reservatet består av betad fälad, alltså gammal öppen betesmark, i sydost och nordväst. Resten av området är stenmarker med tunt jordlager, där sandstenen ofta syns i dagen. Det ger ett öppet och lite karg landskap som skiljer sig från slätten runt omkring. Hit är det nära från stan, så det passar bra för en kortare promenad.' where id = 161; -- Bäckhalladalen
update public.places set short_description = 'Strövområde vid fiskeläget Vitemölla', description = 'Vitemölla är ett litet fiskeläge vid Mölleåns utlopp, någon kilometer norr om Kivik. Mellan Vitemölla och Kivik hålls den årliga Kiviks marknad. Namnet kommer från vattenkvarnen som ligger i byns norra ände. Fiskeläget växte under 1700-talet, från fyra hus år 1699 till över sextio hus på 1870-talet. Runt byn finns sandstrand, strandbackar och natur att ströva i, och norrut går kusten vidare mot Haväng. Det är ett fint område för promenader, bad och utsikt över Hanöbukten.' where id = 162; -- Vitemölla strövområde
update public.places set short_description = 'Böljande backlandskap, känt för sin flora', description = 'Brösarps backar är backlandskapet runt Brösarp och bygdens mest kända kännetecken. Backarna bildades av avlagringar från senaste istiden och består främst av kalkrik mo och sand. De hålls öppna genom bete och är kända för sin flora. I de södra backarna blommar gullviva, backsippa och mandelblomma, och i de större norra backarna växer bland annat sandnejlika och sandlilja. Flera vandringsleder går genom området, och den längsta är Skåneleden. På 1930-talet kom Prins Eugen hit flera somrar för att måla backarna.' where id = 163; -- Brösarps Backar
update public.places set short_description = 'Skånes största vattenfall', description = 'Hallamölla är Skånes största vattenfall, med en sammanlagd fallhöjd på 23 meter. Fallet är en del av Verkeån, vars lopp är skyddat som naturreservat. Namnet kommer från kvarnen som har funnits på platsen sedan 1400-talet. Längs ån fanns förr flera små industrier, som vadmalsstamp, färgeri och mjölkvarnar. I dag finns en kvarn kvar, med stort kvarnhjul, kvarnhus och drängkammare. Från Hallamölla kan man vandra längs Verkeån genom ravinen, och platsen är särskilt fin när det är mycket vatten i ån.' where id = 166; -- Hallamölla
update public.places set short_description = 'Ovanlig formation i sandstenen vid Vik', description = 'Prästens badkar är en ovanlig geologisk formation strax söder om fiskeläget Vik. Den kallas trattsänka och är troligen en så kallad sandvulkan, som bildades för omkring 500 miljoner år sedan när en källa trängde upp vatten genom en havsbotten. Innan sanden hunnit bli sten rasade formationen ihop. På Österlen finns omkring hundra sådana badkar, men det här är det enda som syns. Runt badkaret är sandstenen full av spårfossil, som i folkmun kallas kråksparkar. Platsen ligger vid stranden och är lätt att besöka.' where id = 167; -- Prästens badkar
update public.places set short_description = 'Sandstäpp, ljunghed och bokskog norr om Brösarp', description = 'Drakamöllan är ett naturreservat som bildades 2006. Det är 162 hektar stort och ingår i Natura 2000. Namnet kommer från mjölnaren Drake, som drev en kvarn i Julebodaån. Här finns sandstäpp på kalkrik sandjord, ljunghed som blommar på sensommaren och bokskog. I området lever ovanliga arter som sandödla och sandbi, och här växer sandlilja. Den vita slingan är 3 kilometer, och Blåvingeleden på 9 kilometer går genom flera reservat. Parkering finns vid infarten till Drakamöllans gårdshotell, 5 kilometer norr om Brösarp.' where id = 168; -- Drakamölla
update public.places set short_description = 'Stenåldersgrav vid Verkeåns mynning', description = 'Havängsdösen är en stenkammargrav från yngre stenåldern, omkring 5500 år gammal. Den ligger på Haväng, strax norr om Verkeåns utlopp i Hanöbukten. Gravkammaren består av tre sidostenar med en stor takhäll ovanpå, och runt graven står 16 stenblock som bildar en rektangel på cirka 60 kvadratmeter. Dösar med en sådan kantkedja kallas långdösar. Ingången till kammaren är vänd mot havet, i den riktning där solen går upp vid vår- och höstdagjämningen. Från platsen har man fin utsikt över havet och strandängarna.' where id = 169; -- Havängsdösen
update public.places set short_description = 'Djup dalgång med rikt djurliv', description = 'Fyledalen är en dalgång som är 20 kilometer lång, några hundra meter bred och upp till 50 meter djup. Den ligger på gränsen mellan Sjöbo, Ystads och Tomelilla kommun. År 2015 bildades ett naturreservat på 853 hektar, och dalen ingår i Natura 2000. Här finns många arter av fladdermöss, svampar och skalbaggar, och dalen är känd för sina örnar. Fyledalen har också tydliga geologiska spår från istiden och används ofta för forskning och undervisning. Det finns gott om stigar för den som vill vandra.' where id = 171; -- Fyledalen
update public.places set short_description = 'Kyrka med kalkmålningar från 1400-talet', description = 'Gladsax kyrka, även kallad Sankt Jacobs kyrka, byggdes på 1100-talet i romansk stil. På 1400-talet fick den valv och ett torn. År 1857 revs det gamla koret, och i stället byggdes tre korsarmar med ett nytt, tresidigt kor. Tornet byggdes om 1883. I långhuset finns kalkmålningar som Nils Håkansson utförde i mitten av 1400-talet, och målningarna i korsets mitt är kopior från 1898. Kyrkan tillhör Simrishamns församling och ligger i Gladsax, inte långt från Simrishamn.' where id = 173; -- Gladsax Kyrka
update public.places set short_description = 'Liten romansk kyrka med gravvalv', description = 'Östra Vemmerlövs kyrka byggdes på 1100-talet som en liten romansk kyrka med långhus och ett smalare kor. På 1400-talet förlängdes långhuset västerut, kyrkan fick kryssvalv och stentornet byggdes. Den ursprungliga kyrkan hade en ingång i norr för kvinnorna och en i söder för männen, och på 1400-talet byggdes vapenhus framför dem. Under korgolvet finns två gravvalv, varav det ena hör till släkten Knob-Urne. Kyrkan tillhör Gärsnäs församling och ligger i byn Östra Vemmerlöv.' where id = 175; -- Östra Vemmerlövs Kyrka
update public.places set short_description = 'Vitkalkad gråstenskyrka från 1862', description = 'Onslunda kyrka ligger mitt i Onslunda. När biskop Wilhelm Faxe besökte den gamla kyrkan 1838 var den i mycket dåligt skick, och några år senare beslutade socknen att bygga en ny. Den nuvarande kyrkan uppfördes 1862 av gråsten, med inspiration från romansk stil. Tornet har trappgavel och är ganska smalt jämfört med det rymliga långhuset, och i andra änden finns en halvrund absid med sakristia. Kyrkan är vitkalkad. Ovanför västportalen sitter en skylt om att kyrkan byggdes under kung Karl XV. Kyrkan tillhör Brösarp-Tranås församling.' where id = 176; -- Onslunda Kyrka
update public.places set short_description = 'Kyrka byggd på medeltida gråstensmurar', description = 'Stiby kyrka ligger i Stiby nära Gärsnäs. Innan den byggdes fanns här en medeltida kyrka, och när den nuvarande kyrkan uppfördes 1856 återanvändes de gamla gråstensmurarna. Kyrkan har långhus, trappgavelstorn i väster och halvrund absid i öster. Två föremål finns kvar från den gamla kyrkan: predikstolen från 1600-talet och en akvamanil, ett tvättkärl, från 1200-talet. Altartavlan är en kopia från 1887 av Carl Blochs målning i Löderups kyrka. Kyrkan är församlingskyrka i Gärsnäs församling.' where id = 186; -- Stiby Kyrka
update public.places set short_description = 'Tegelkyrka med altaruppsats från 1507', description = 'Tranås kyrka i Skåne-Tranås byggdes 1880 i rött tegel och nyromansk stil efter ritningar av Peter Boisen. Den ersatte en romansk kyrka från 1000- eller 1100-talet. Tornet är 33 meter högt och kröns av ett kopparkors. Flera föremål kommer från den gamla kyrkan: dopfunten från 1100-talet och ett triumfkrucifix från 1200-talet. Altaruppsatsen är från 1507 och predikstolen från 1603. Kyrkans storklocka är en av de äldsta i stiftet. Kyrkan tillhör Brösarp-Tranås församling.' where id = 187; -- Tranås Kyrka
update public.places set short_description = 'Kyrka med välbevarade kalkmålningar', description = 'Östra Herrestads kyrka byggdes troligen i mitten av 1100-talet i romansk stil. Sydportalen är ursprunglig, och på den står inskriptionen Carl Stenmester scar denna sten, som gett stenmästaren Carl hans namn. Valven slogs på 1400-talet, och 1888–1889 förlängdes kyrkan och fick sitt nuvarande torn. Kyrkan har många kalkmålningar från slutet av 1400-talet, och bildprogrammet är nästan helt bevarat. Målningarna kalkades över, upptäcktes igen 1885 och restaurerades 1933. Kyrkan tillhör Gärsnäs församling.' where id = 188; -- Östra Herrestad Kyrka
update public.places set short_description = 'Kyrka invigd på kyndelsmässodagen 1880', description = 'Rörums kyrka byggdes 1879 och invigdes den 1 februari 1880, på kyndelsmässodagen. Byns gamla medeltidskyrka låg söder om den nuvarande, på det som i dag kallas gamla kyrkogården. Den ansågs för liten och i dåligt skick, och redan på 1830-talet diskuterade man att bygga en ny. När den gamla kyrkans torn rasade 1838 blev frågan mer akut, men det dröjde ändå till 1877 innan bygget startade. Kyrkan ritades av A Silvander. Den är församlingskyrka i Simrishamns församling.' where id = 189; -- Rörums Kyrka
update public.places set short_description = 'Nygotisk korskyrka nära Kivik', description = 'Södra Mellby kyrka är en korskyrka i nygotisk stil, byggd 1885–1887 efter ritningar av Fredrik Ekberg. Den ersatte en kyrka från 1200-talet. Flera föremål finns kvar från den medeltida kyrkan: dopfunten i kalksten från början av 1200-talet, som troligen höggs av stenmästaren Calcarius II, predikstolen från början av 1600-talet och altaruppsatsen i barockstil från 1669. Orgeln byggdes 1889 och är mekanisk. Kyrkan tillhör Kiviks församling och ligger i Södra Mellby, strax väster om Kivik.' where id = 191; -- Södra Mellby Kyrka
update public.places set short_description = 'Sveriges första bokby, full av antikvariat', description = 'Borrby Bokby kallar sig Sveriges första bokby. Det är en by med ovanligt många antikvariat, där man kan gå från ställe till ställe och leta efter gamla och nya böcker. Borrby ligger mellan Simrishamn och Ystad och kallas ibland Österlens hjärta. Orten växte fram som stationssamhälle efter att järnvägen Ystad–Gärsnäs öppnade 1894. Diktaren Theodor Tufvesson föddes i Borrby. Bokbyn ordnar också olika evenemang, och information om dem läggs upp på Facebook. Kolla gärna öppettiderna innan ni åker.' where id = 192; -- Borrby Bokby 
update public.places set short_description = 'Romansk kyrka vid den gamla landsvägen', description = 'Fågeltofta kyrka ligger en bit öster om byn Fågeltofta, vid den gamla landsvägen. Den byggdes på 1100-talet i romansk stil, med ett långhus som är bredare än koret och absiden. På 1400-talet byggdes kyrkan till i norr och fick stjärnvalv. Tornet byggdes 1818, och då revs den klockstapel som tidigare stått vid kyrkan. Predikstolen är från början av 1600-talet och har vapen som hör ihop med ägaren till Kronovalls slott. Kyrkan tillhör Brösarp-Tranås församling.' where id = 194; -- Fågeltofta Kyrka
update public.places set short_description = 'Medeltida kyrka som använts som försvar', description = 'Vitaby kyrka ligger i Vitaby kyrkby och är från 1100-talet. Kyrkan har också använts som försvarsanläggning. Tornet tillkom på 1200-talet, och strävpelarna byggdes för att motverka svängningar när klockorna ringde. På 1400-talet tillkom vapenhuset och valven, och 1781 byggdes en korsarm åt norr. I koret finns kalkmålningar från 1300- och 1400-talen, de senare av Fjälkingemästaren. Kyrkan har ett triumfkrucifix från 1200-talet och en predikstol från 1614. Den tillhör Kiviks församling.' where id = 197; -- Vitaby Kyrka
update public.places set short_description = 'Medeltida tegelkyrka helgad åt Sankta Gertrud', description = 'Eljaröds kyrka ligger mitt i byn Eljaröd och är helgad åt Sankta Gertrud. Den byggdes på 1200-talet av tegel på en grund av gråsten. Från början hade den bara långhus och kor, och i slutet av medeltiden byggdes torn och vapenhus till. I kyrkan finns flera föremål från medeltiden: dopfunten och ett krucifix från 1200-talet, och en madonnaskulptur i trä från samma tid som kom tillbaka till kyrkan 1966. Kyrkan står mitt i en medeltida kyrkogård och tillhör Brösarp-Tranås församling.' where id = 198; -- Eljaröds Kyrka
update public.places set short_description = 'Konstnärshem och ateljé nära Kivik', description = 'Ateljé Ekberga är ett konstnärshem i den lilla byn Södra Mellby, nära Kivik. Här kan man se konst i den miljö där den skapas, och möta konstnären i ateljén. Södra Mellby ligger strax väster om Kivik, med fruktodlingar, Stenshuvud och kusten i närheten, så ett besök passar bra ihop med en tur i trakten. Ateljén är aktiv på Instagram, där man kan se aktuella verk. Kolla gärna öppettiderna innan ni åker, eftersom ateljéer ofta har öppet vid vissa tider eller efter överenskommelse.' where id = 201; -- Ateljé Ekerberga Österlen
update public.places set short_description = 'Romansk kyrka med kalkmålningar från 1200-talet', description = 'Brösarps kyrka byggdes på 1100-talet i romansk stil. På 1200-talet målades kalkmålningar som delvis finns kvar. Kyrkan fick en norra korsarm i slutet av 1700-talet och en södra omkring 1860, då även tornet byggdes om. Samtidigt togs 1400-talsvalven bort, och de tidiga målningarna kom fram igen. De finns på triumfbågen och i absiden och visar främst Kristus med evangelister och apostlar. Dopfunten av granit är från 1100- eller 1200-talet. På kyrkogården ligger Hanna Johansdotter begravd, offret i Yngsjömordet.' where id = 211; -- Brösarps Kyrka
update public.places set short_description = 'Dag Hammarskjölds gård vid havet', description = 'Backåkra är en fyrlängad gård som köptes av Dag Hammarskjöld, FN:s andre generalsekreterare. Den ligger mellan Löderups strandbad och Sandhammaren. Sedan 2015 ägs gården av Stiftelsen Dag Hammarskjölds Backåkra. Här finns ett museum om Hammarskjöld, ett café och en liten bokhandel, och gården används också för konferenser. Runt Backåkra finns ett öppet landskap med havet i närheten. Ett besök passar bra ihop med en promenad på Sandhammaren eller en tur till Kåseberga och Ales stenar.' where id = 212; -- Backåkra 
update public.places set short_description = 'Husmanshus som visar hur fattiga bodde', description = 'Örumshuset är ett husmanshus i Örum, cirka två mil öster om Ystad. Huset byggdes vid sekelskiftet 1800, i samband med enskiftet. Eftersom det ligger isolerat ute på slätten har det förblivit oförändrat. Det är en skånelänga, med bostad och fähus under samma tak. Huset var bebott till 1948, blev byggnadsminne 1959 och är i dag ett museum som visar hur fattigt folk bodde förr. En husman var en lantarbetare, hantverkare eller soldat som ägde sitt hus men ingen del av byns jord.' where id = 215; -- Örumshuset
update public.places set short_description = 'Bad- och strövområde söder om Brantevik', description = 'Grönet ligger strax söder om fiskeläget Brantevik och är ett bad- och strövområde med betade hagmarker och klippstränder. Här kan man promenera längs kusten, bada från klipporna eller bara sitta och titta ut över havet. Brantevik ligger ungefär fem kilometer söder om Simrishamn och hade kring år 1900 Sveriges största handelsflotta räknat i antal fartyg. Eftersom byn låg i två socknar har den två hamnar. Ett besök på Grönet passar fint ihop med en promenad genom byn.' where id = 216; -- Grönet Brantevik
update public.places set short_description = 'Strandängar och fågelliv söder om Simrishamn', description = 'Simris strandängar är ett naturreservat vid kusten strax söder om Simrishamn. Det har varit skyddat sedan 1959, är 34,5 hektar stort och ingår i Natura 2000. Reservatet består av öppen fäladsmark med sandstrand, strandängar, torrängar och kalkkärr. Här häckar tofsvipa, och längs stranden syns knölsvanar, änder och vadare som rödbena. I vattensamlingarna lever lövgroda, och här växer salttåliga växter och ovanliga orkidéer. Skåneleden går genom området, så det är lätt att ta en promenad hit från stan.' where id = 217; -- Simris Strandängar 
update public.places set short_description = 'Skånes bäst bevarade hällristningar', description = 'Järrestads hällristningar är Skånes bäst bevarade hällristningar och en av Nordens största hällristningsplatser. De ligger i en hage ungefär en kilometer norr om Järrestad, vid vägen mot Gladsax. På hällen finns över 1200 bilder, bland annat skepp, ryttare, spiraler, djur, omkring 700 skålgropar och runt 210 fotsulor. Mest känd är en stor människofigur som kallas Dansaren, och därför kallas platsen också Dansarens häll. Ristningarna är från bronsåldern, och i närheten finns tre låga gravhögar från samma tid. Gå försiktigt på hällen.' where id = 218; -- Järrestad hällristning 
update public.places set short_description = 'Gammalt slott vid Smedstorpsdammen', description = 'Smedstorps slott ligger i en park intill den lilla Smedstorpsdammen. På 1500-talet var det en stor slottsanläggning, men i dag finns bara borgens västra länga kvar. Godset hör till de äldre i Skåne och ägdes 1313–1589 av släkten Bing. Den siste av släkten, Anders Bing, hade kung Jakob I av England som gäst, och kungens dikt till honom finns på Bings gravmonument vid Smedstorps kyrka. Senare ägdes slottet bland annat av familjen Hemberg. Observera att slottet inte är öppet för allmänheten.' where id = 225; -- Smedstorps slott
update public.places set short_description = 'Åttkantig gård från 1775', description = 'Södra Björstorps gård är en gammal herrgård som också kallats slott. Huvudbyggnaden uppfördes 1775 av Mickael Malmström, som troligen var inspektör vid Andrarums alunbruk. Gården är helt kringbyggd och åttkantig, en form som inte finns någon annanstans i Sverige. Marken runt gården har troligen odlats sedan högmedeltiden, och området skyddades som kulturminne 1977. Den 9 september 2018 förstördes gården i en brand, och bara väggarna stod kvar. Hösten 2021 hade den byggts upp igen. Gården ligger nära Brösarp.' where id = 227; -- Södra Björstorp
update public.places set short_description = 'Keramikverkstad och butik i Baskemölla', description = 'Elisabeth Kajsa Palm är keramiker och har sin verkstad och butik i Baskemölla på Österlen. Här kan man se var keramiken tillverkas och köpa den direkt från keramikern. Baskemölla är ett litet fiskeläge norr om Simrishamn, med gamla hus och nära till havet, och kustvägen hit passerar flera andra konsthantverkare. Ett besök passar bra ihop med en promenad längs kusten mot Vik eller Simrishamn. Kolla gärna öppettiderna innan ni åker, eftersom verkstäder ofta har öppet vissa tider.' where id = 230; -- Elisabeth Kajsa Palm Keramik
update public.places set short_description = 'Keramikverkstad längs kustvägen vid Kåseberga', description = '912 Kåseberga ligger längs Kustvägen mellan Kåseberga och Löderups strandbad. Här har keramikern Elna-Karin Helgesson sin verkstad och butik, där man kan se keramiken och köpa den direkt på plats. Hon har många följare i sociala medier, där man kan se hennes arbeten. Läget gör det lätt att stanna till under en tur längs sydkusten, till exempel på väg till eller från Ales stenar i Kåseberga eller stranden i Löderup. Kolla gärna öppettiderna innan ni åker.' where id = 234; -- 912 Kåseberga
update public.places set short_description = 'Galleributik med lokalt konsthantverk', description = 'Konsthantverksgruppen KAOS är en grupp konsthantverkare som har en gemensam galleributik på Svabesholms Kungsgård i Svinaberga, strax utanför Kivik. Här säljs lokalt konsthantverk, och eftersom flera hantverkare står bakom butiken finns det en bredd av material och uttryck. Svabesholm är en gammal kungsgård i Kivikstrakten, med fruktodlingar och Stenshuvud i närheten. Ett besök passar bra ihop med en tur till Kivik, Stenshuvud eller trakten runt. Kolla gärna öppettiderna innan ni åker.' where id = 242; -- Konsthantverksgruppen Kaos 
update public.places set short_description = 'Galleri med utställningar och konsthantverk', description = 'Galleri1 i Tomelillatrakten visar utställningar under hela sommarhalvåret. Förutom utställningarna finns här konsthantverk till försäljning, och en del av det som säljs är galleriets egen produktion. Det gör att man kan komma hit både för att titta på konst och för att hitta något att ta med sig hem. Tomelilla ligger på västra Österlen, med Fyledalen och Kronovalls slott inte långt bort. Kolla gärna aktuella utställningar och öppettider innan ni åker, eftersom galleriet främst har öppet under sommarhalvåret.' where id = 259; -- Galleri1
update public.places set short_description = 'Frukt- och grönsaksbutik i Tomelilla', description = 'Tomelillas Frukt & Grönt är en lokal butik i Tomelilla som, som namnet säger, säljer frukt och grönsaker. Här kan man handla färska råvaror till matlagningen hemma eller till picknicken under en dag på Österlen. Tomelilla är en av Österlens större orter, och butiken är ett bra komplement till de större matbutikerna. Österlen är känt för sina odlingar, så under säsong kan det vara värt att hålla utkik efter det som odlas i trakten. Kolla gärna öppettiderna innan ni åker.' where id = 264; -- Tomelillas Frukt & Grönt
update public.places set short_description = 'ICA-butik mitt i Borrby', description = 'ICA Supermarket Klockareboden är matbutiken i Borrby. Här handlar man dagligvaror, och det är en praktisk plats att fylla på förråden under en semester i trakten, till exempel om man bor i stuga eller campar. Borrby ligger mellan Simrishamn och Ystad och kallas ibland Österlens hjärta. Från orten är det nära till kusten vid Borrby strand och Skillinge, och i byn finns också Borrby Bokby med sina antikvariat. Butiken är aktiv i sociala medier, där man kan se nyheter och erbjudanden.' where id = 268; -- ICA Supermarket Klockareboden i Borrby
update public.places set short_description = 'Butik och trädgård med medelhavskänsla', description = 'En liten bit av Medelhavet i Hammenhög är en butik med trädgård, som bjuder in besökare att uppleva lite av Medelhavet mitt på Österlen. Här kan man gå runt i trädgården och handla i butiken. Butiken har många följare på Facebook och Instagram, där man kan se vad som finns just nu. Hammenhög ligger mitt på södra Österlen, mellan Simrishamn och Ystad, så ett besök passar bra under en tur i trakten. Kolla gärna öppettiderna innan ni åker, eftersom de kan variera med säsongen.' where id = 279; -- En liten bit av Medelhavet
update public.places set short_description = 'Klädbutik i Simrishamn för alla åldrar', description = '1910 Simrishamns Modehus är en klädbutik i Simrishamn med skandinaviskt mode för både kvinnor och män i alla åldrar. Här kan man hitta allt från vardagskläder till något lite finare, och butiken lägger ofta upp nyheter på Instagram. Simrishamn är Österlens största ort, och centrum har många mindre butiker längs gatorna nära hamnen. Butiken passar bra att besöka under en shoppingrunda i stan, kanske kombinerat med en fika eller en promenad vid hamnen. Kolla gärna öppettiderna innan.' where id = 280; -- 1910 Simrishamns Modehus
update public.places set short_description = 'Livsstilsbutik med inredning och kläder', description = 'Ting & Tang är en livsstilsbutik i Simrishamn med heminredning och en del kläder. Butiken drivs av Hege Welin och delar mycket av sitt sortiment och sin vardag på Instagram, där den har många följare. Här kan man hitta saker till hemmet, presenter och kläder, och det mesta är valt för att vara skönt att ha och använda. Simrishamn har många små butiker i centrum, så Ting & Tang passar bra att besöka under en runda i stan. Kolla gärna öppettiderna innan.' where id = 283; -- Ting & Tang
update public.places set short_description = 'ICA Nära i Gärsnäs, öppen alla dagar', description = 'Häggs Livs är en ICA Nära-butik i Gärsnäs, och den har öppet alla dagar i veckan. Här kan man handla dagligvaror, vilket är praktiskt för den som bor i stuga eller på camping i trakten. Gärsnäs ligger mitt på södra Österlen, mellan Simrishamn och Tomelilla, med många av bygdens medeltida kyrkor i närheten. Butiken lägger upp nyheter och erbjudanden på Instagram. En bra plats att stanna till för att handla på väg till eller från kusten. Kolla gärna aktuella öppettider.' where id = 288; -- Häggs Livs
update public.places set short_description = 'Choklad och godis utan socker eller gluten', description = 'Trendigt gott i Hammenhög säljer choklad, godis och lakrits som är veganskt, glutenfritt, laktosfritt och/eller sockerfritt. Det gör butiken till ett bra ställe för den som har allergier eller vill undvika vissa ingredienser, men ändå vill unna sig något sött. Här finns ofta produkter som är svåra att hitta i vanliga matbutiker. Butiken visar sitt sortiment på Instagram. Hammenhög ligger mitt på södra Österlen, så ett besök passar bra under en tur i trakten. Kolla gärna öppettiderna innan.' where id = 290; -- Trendigt gott
update public.places set short_description = 'ICA Supermarket i Brösarp', description = 'Götes Allköp är ICA Supermarket i Brösarp. Butiken fyller på med färskvaror varje dag och har det mesta man behöver, både till vardagsmaten och till festen. Det gör den till ett praktiskt stopp för den som bor i stuga eller på camping på norra Österlen. Brösarp är känt för sina backar, och härifrån är det nära till Haväng, Stenshuvud och kusten vid Hanöbukten. En bra plats att handla inför en picknick eller en dag i naturen. Kolla gärna aktuella öppettider innan.' where id = 292; -- Götes Allköp i Brösarp
update public.places set short_description = 'Bokhandel i Simrishamn, öppen alla dagar', description = 'Simrishamns Bokhandel öppnade i augusti 2020 och har öppet alla dagar i veckan. Här kan man hitta något att läsa, både skönlitteratur och böcker av andra slag, och en bokhandel är också ett bra ställe att hitta presenter på. Simrishamn är Österlens största ort, och bokhandeln passar bra att besöka under en promenad i centrum eller vid hamnen. För den som vill läsa om trakten kan det vara värt att fråga efter böcker om Österlen. Kolla gärna aktuella öppettider.' where id = 294; -- Simrishamns Bokhandel 
update public.places set short_description = 'Stor blomsteraffär med växter och inredning', description = 'Ullstorps Gardencenter är en stor blomsteraffär på Österlen, i närheten av Tomelilla. Sortimentet sträcker sig från inredning och snittblommor till krukväxter för inomhus och växter för trädgården. Här kan man alltså hitta både en bukett till någon och plantor att sätta i rabatten hemma. Butiken passar bra att besöka under säsongen för trädgård, men också inför helger och högtider. Ullstorp ligger strax norr om Tomelilla. Kolla gärna öppettiderna innan ni åker, eftersom de kan variera med säsongen.' where id = 295; -- Ullstorps Gardencenter
update public.places set short_description = 'Inredningsbutik på Österlen', description = 'Studio Billa är en inredningsbutik på Österlen, i närheten av Simrishamn. Butiken har många följare på Instagram, där den visar sitt sortiment och sina nyheter, och det är ett bra sätt att se vad som finns innan man åker dit. Här kan man hitta saker till hemmet och presenter. Simrishamn och trakten runt har många små butiker med inredning och hantverk, så Studio Billa passar bra att besöka under en shoppingrunda i området. Kolla gärna öppettiderna innan ni åker.' where id = 297; -- Studio Billa
update public.places set short_description = 'Gårdsbutik med närproducerat utanför Hammenhög', description = 'Hemdala Gårdsbutik ligger strax utanför Hammenhög och säljer närproducerat och närodlat från Österlen. Här kan man handla kött, honung, mjöl och grönsaker efter säsong, med mera. Det gör butiken till ett bra ställe för den som vill laga mat på råvaror från trakten. En gårdsbutik som denna ger också en känsla för det jordbrukslandskap som präglar södra Österlen. Butiken visar sitt sortiment på Facebook och Instagram. Kolla gärna öppettiderna innan ni åker, eftersom gårdsbutiker ofta har begränsat öppet.' where id = 302; -- Hemdala Gårdsbutik
update public.places set short_description = 'Fristående sportbutik i Tomelilla', description = 'N-Sport är en fristående sportbutik i Tomelilla, alltså inte en del av en stor kedja. Butiken lägger vikt vid god service och har ett sortiment med lite av varje inom sport och fritid. Här kan man hitta utrustning och kläder för träning, idrott och friluftsliv, och få hjälp att välja rätt. Butiken lägger ofta upp nyheter på Instagram. För den som ska ut och vandra eller cykla på Österlen kan det vara ett bra ställe att komplettera utrustningen. Kolla gärna öppettiderna innan.' where id = 316; -- N-Sport Tomelilla
update public.places set short_description = 'Minigolf och kiosk vid Löderups strandbad', description = 'Löderups Strandbads Minigolf & Kiosk ligger vid Löderups strandbad på sydkusten. Minigolfen har öppet under sommaren, från midsommar till slutet av augusti, och den har öppet långt in på kvällen. Det gör den till ett bra ställe för familjer och vänner som vill göra något roligt efter en dag på stranden. I kiosken kan man köpa något att äta eller dricka. Löderups strandbad har en lång sandstrand, och Sandhammaren och Kåseberga ligger inte långt bort. Kolla gärna aktuella öppettider på Facebook.' where id = 328; -- Löderups Strandbads Minigolf & Kiosk
update public.places set short_description = 'Bed and breakfast nära Skillinge', description = 'Lunkaberg B&B är ett bed and breakfast på Österlen, nära Skillinge på sydostkusten. Här kan man bo och äta frukost, och det är en bra bas för den som vill upptäcka både kusten och inlandet. Skillinge är ett gammalt fiskeläge med hamn, och längs kusten finns flera små fiskelägen och klippstränder, som Brantevik och Gislövshammar. Boendet lägger upp bilder och nyheter på Instagram, där man kan se hur det ser ut. Boka gärna i förväg, särskilt under sommaren.' where id = 340; -- Lunkaberg B&B
update public.places set short_description = 'Kyrka med Carl Blochs altartavla', description = 'Löderups kyrka har ett långhus och ett brett västtorn från 1100-talet, och kyrkan välvdes på 1400-talet. År 1860 revs det gamla koret och absiden under ledning av Carl Georg Brunius, och i stället byggdes två korsarmar och ett nytt tresidigt kor. Dopfunten är från omkring 1160 och gjord av Trydemästaren, med bilder ur Kristi lidande och legender om Sankt Olof. Predikstolen från 1604 är gjord av Jacob Kremberg. Altartavlan är målad av Carl Bloch och har kopierats i flera andra kyrkor. Kyrkan är församlingskyrka i Löderups församling.' where id = 360; -- Löderups Kyrka
commit;
